      }
    }
  ],
  "story_facts": [
    "玩家目前正处于哥布林设在‘祭祀祭坛’的合围中心，退路已被数十只组织化的哥布林封锁",
    "‘受伤新人’事件进入爆发态：新人的惨叫吸引了所有潜伏哨兵，玩家已被迫卷入第一场遭遇战"
  ],
  "strategy_notes": "叙事停滞彻底突破，进入‘强制推进’模式。由于玩家无视所有外部阻碍直达祭坛，NarrativeWeaver 将不再提供温和引导。接下来的重点是利用‘害虫级威胁规则’，让玩家亲身体会到鲁莽的代价：大量的哥布林将获得群体士气加成，且环境中弥漫的血腥气将引来更强的敌人。此次战斗的结果将直接决定玩家在公会信用的降级程度（若抛弃新人则视为信用破产）。"
}

{
  "directives": [
    {
